import React from 'react';

const CurriculumBuilder = ({ modules, setModules }) => {
  const addModule = () => {
    setModules([...modules, { title: '', order: modules.length + 1, content: [] }]);
  };

  const addContent = (mIdx, type) => {
    const newModules = [...modules];
    const newItem = {
      title: '',
      type: type, // 'video' or 'quiz'
      order: newModules[mIdx].content.length + 1,
      ...(type === 'quiz' ? { quizData: { questions: [] } } : { videoUrl: '', duration: 0 })
    };
    newModules[mIdx].content.push(newItem);
    setModules(newModules);
  };

  return (
    <div className="curriculum-container" style={{ background: '#0f172a', padding: '20px', borderRadius: '12px' }}>
      <h2 style={{ color: '#fff' }}>Course Curriculum</h2>
      {modules.map((mod, mIdx) => (
        <div key={mIdx} style={{ border: '1px solid #334155', padding: '15px', marginBottom: '15px' }}>
          <input 
            placeholder="Module Title" 
            value={mod.title}
            onChange={(e) => {
              const next = [...modules];
              next[mIdx].title = e.target.value;
              setModules(next);
            }}
            style={{ width: '100%', marginBottom: '10px', padding: '8px' }}
          />
          
          {mod.content.map((item, iIdx) => (
            <div key={iIdx} style={{ marginLeft: '20px', borderLeft: '2px solid #7c3aed', padding: '10px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#a78bfa' }}>{item.type.toUpperCase()}</span>
                <input 
                  placeholder="Item Title" 
                  value={item.title}
                  onChange={(e) => {
                    const next = [...modules];
                    next[mIdx].content[iIdx].title = e.target.value;
                    setModules(next);
                  }}
                />
              </div>
              {item.type === 'video' && (
                <input 
                  placeholder="Video URL" 
                  value={item.videoUrl} 
                  onChange={(e) => {
                    const next = [...modules];
                    next[mIdx].content[iIdx].videoUrl = e.target.value;
                    setModules(next);
                  }}
                  style={{ width: '100%', marginTop: '5px' }}
                />
              )}
            </div>
          ))}
          <button type="button" onClick={() => addContent(mIdx, 'video')}>+ Add Video</button>
          <button type="button" onClick={() => addContent(mIdx, 'quiz')}>+ Add Quiz</button>
        </div>
      ))}
      <button type="button" onClick={addModule} style={{ background: '#7c3aed', color: 'white' }}>Add Module</button>
    </div>
  );
};

export default CurriculumBuilder;
